import{c as e,Z as o,Q as i,j as r,m as l,o as n}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"清江引·秋怀","description":"","frontmatter":{"title":"清江引·秋怀","author":"张可久","dynasty":"元"},"headers":[],"relativePath":"books/shici/yuanqu/10.md","filePath":"books/shici/yuanqu/10.md"}'),s={name:"books/shici/yuanqu/10.md"};function h(u,a,c,p,d,q){const t=o("PoemNav");return i(),r("div",null,[a[0]||(a[0]=l('<h1 id="清江引·秋怀" tabindex="-1">清江引·秋怀 <a class="header-anchor" href="#清江引·秋怀" aria-label="Permalink to &quot;清江引·秋怀&quot;">​</a></h1><p><strong>[元] <a href="/authors/zhangkejiu.html">张可久</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>西风信来家万里，问我归期未？雁啼红叶天，人醉黄花地，芭蕉雨声秋梦里。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>清江引：曲牌名</li><li>秋怀：秋日里的情怀</li><li>西风：秋风</li><li>信来：来信</li><li>归期：回家的日期</li><li>雁啼：大雁啼叫</li><li>红叶天：枫叶变红的秋天</li><li>黄花地：菊花盛开的地面</li><li>芭蕉雨声：雨打芭蕉的声音</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>秋风送来家书，来自万里之外的家乡，问我何时归去。大雁在红叶满天的季节啼叫，人在菊花盛开的地方醉酒，在雨打芭蕉的声音中进入秋梦。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首小令是张可久的代表作，描写了秋日里的思乡之情，是元曲中写秋怀的佳作。</p><p>&quot;西风信来家万里，问我归期未&quot;，开篇就点明了思乡的主题。秋风送来家书，来自万里之外的家乡，家人问我何时归去。&quot;问我归期未&quot;，既是家人的询问，也是词人自己的自问，将思乡之情表现得深切动人。</p><p>&quot;雁啼红叶天，人醉黄花地&quot;，写秋日的景象。大雁啼叫，红叶满天，黄花遍地，词人借酒浇愁。这里的&quot;醉&quot;，既是醉酒，也是沉醉于秋色之中，更是借酒排遣乡愁。</p><p>&quot;芭蕉雨声秋梦里&quot;，以雨打芭蕉的声音作结，将词人带入秋梦之中。芭蕉雨声是秋夜的典型意象，既增添了秋意，又加深了乡愁。</p><p>全曲语言清丽，意境优美，将思乡之情与秋日景色完美融合，体现了张可久散曲清雅的风格。</p><hr><h2 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h2><blockquote><p><strong>张可久</strong>（约1270年－1348年后），字小山，元代著名散曲家。其散曲多写山水隐逸和闺情，风格清丽典雅，是元代散曲清丽派的代表。</p><p><a href="/authors/zhangkejiu.html">查看作者详情 →</a></p></blockquote>',17)),n(t)])}const b=e(s,[["render",h]]);export{m as __pageData,b as default};
